function initSocialSwitch(){
  const btns = document.querySelectorAll('.snav-btn');
  btns.forEach(btn=>{
    btn.addEventListener('click', ()=>{
      btns.forEach(b=>b.classList.toggle('active', b===btn));
      document.querySelectorAll('.social-pane').forEach(p=>p.classList.remove('active'));
      document.getElementById('pane-'+btn.dataset.social).classList.add('active');
    });
  });
}

/* download an image (dataURL or remote) */
async function downloadImage(src, name){
  try{
    if(src.startsWith('data:')){
      const a=document.createElement('a'); a.href=src; a.download=name; a.click();
    } else {
      const r=await fetch(src); const b=await r.blob();
      const u=URL.createObjectURL(b); const a=document.createElement('a'); a.href=u; a.download=name; a.click();
      setTimeout(()=>URL.revokeObjectURL(u), 1000);
    }
    toast(t('toast.downloaded'));
  }catch(e){ window.open(src,'_blank'); }
}

const openComments = new Set();

function renderSocial(){ seedSocialData(); renderFeed(); renderTop(); renderNotifs(); }

function timeShort(k){
  const map = {
    az:{h:'saat əvvəl',d:'gün əvvəl',m:'dəq əvvəl'},
    tr:{h:'saat önce',d:'gün önce',m:'dk önce'},
    en:{h:'h ago',d:'d ago',m:'m ago'},
  };
  const m = map[LANG];
  const match = k.match(/^(\d+)([hdm])$/);
  if(!match) return k;
  const [,n,u] = match;
  const suffix = u==='h'?m.h:u==='d'?m.d:m.m;
  return `${n} ${suffix}`;
}

function renderFeed(){
  const seed = store.get('posts', []);
  const posts = [...dbPosts, ...seed];
  const list = document.getElementById('feedList');
  if(posts.length === 0){ list.innerHTML = `<div class="empty-hint">${t('app.noPosts')}</div>`; return; }
  const locale = LANG==='en'?'en-US':LANG==='tr'?'tr-TR':'az-AZ';
  list.innerHTML = '';
  posts.forEach(p=>{
    const comments = Array.isArray(p.comments) ? p.comments : [];
    const isOpen = openComments.has(p.id);
    const el = document.createElement('div');
    el.className = 'post-card';
    el.innerHTML = `
      <div class="post-head">
        <img class="post-avatar" src="${p.avatar}" alt="">
        <div><div class="post-user">${p.user}</div><div class="post-meta">${timeShort(p.time)} · ${p.alt.toLocaleString(locale)} m</div></div>
      </div>
      ${p.img ? `<img class="post-media" src="${p.img}" alt="" loading="lazy">` : ''}
      ${p.caption ? `<div class="post-caption">${p.caption}</div>` : ''}
      <div class="post-actions">
        <button class="post-action like-btn ${p.liked?'liked':''}" aria-pressed="${p.liked}">
          <svg viewBox="0 0 24 24" width="17" height="17"><path fill="currentColor" d="M12 21s-6.5-4.6-9.3-8.2C1 10.2 1.3 6.8 4 5c1.8-1.2 4-.9 5.4.6L12 8.2l2.6-2.6c1.4-1.5 3.6-1.8 5.4-.6 2.7 1.8 3 5.2 1.3 7.8C18.5 16.4 12 21 12 21z"/></svg>
          <span>${p.likes}</span></button>
        <button class="post-action comment-btn" aria-label="comment">
          <svg viewBox="0 0 24 24" width="17" height="17"><path fill="currentColor" d="M20 2H4a2 2 0 00-2 2v18l4-4h14a2 2 0 002-2V4a2 2 0 00-2-2z"/></svg>
          <span>${comments.length}</span></button>
        ${p.img ? `<button class="post-action post-download dl-btn" aria-label="download" title="${t('app.download')}">
          <svg viewBox="0 0 24 24" width="17" height="17"><path fill="currentColor" d="M5 20h14v-2H5v2zM19 9h-4V3H9v6H5l7 7 7-7z"/></svg></button>` : ''}
      </div>
      <div class="post-comments ${isOpen?'open':''}">
        ${comments.map(c=>`<div class="comment-row"><img class="comment-av" src="${c.avatar}" alt=""><div class="comment-bubble"><div class="comment-user">${c.user}</div><div class="comment-text">${escapeHtml(c.text)}</div></div></div>`).join('')}
        <div class="comment-input-row">
          <input class="comment-input" type="text" maxlength="140" placeholder="${t('app.commentPh')}">
          <button class="comment-send">${t('app.send')}</button>
        </div>
      </div>`;

    const likeBtn = el.querySelector('.like-btn');
    likeBtn.addEventListener('click', async ()=>{
      p.liked = !p.liked; p.likes += p.liked ? 1 : -1;
      likeBtn.classList.toggle('liked', p.liked);
      likeBtn.setAttribute('aria-pressed', String(p.liked));
      likeBtn.querySelector('span').textContent = p.likes;
      if(p.liked){ likeBtn.classList.remove('pop'); void likeBtn.offsetWidth; likeBtn.classList.add('pop'); }
      if(p.dbId && SB){
        if(p.liked) await SB.from('likes').insert({post_id:p.dbId, device_id:DEVICE_ID});
        else await SB.from('likes').delete().eq('post_id',p.dbId).eq('device_id',DEVICE_ID);
      } else {
        store.set('posts', seed);
      }
    });
    el.querySelector('.comment-btn').addEventListener('click', ()=>{
      if(openComments.has(p.id)) openComments.delete(p.id); else openComments.add(p.id);
      renderFeed();
    });
    const dl = el.querySelector('.dl-btn');
    if(dl) dl.addEventListener('click', ()=> downloadImage(p.img, `zirve-${p.alt}m.jpg`));

    const box = el.querySelector('.post-comments');
    const input = box.querySelector('.comment-input');
    const send = async ()=>{
      const txt = input.value.trim(); if(!txt) return;
      const profile = getProfile();
      p.comments = comments; p.comments.push({user:profile.username, avatar:profile.avatar, text:txt});
      openComments.add(p.id);
      input.value = '';
      if(p.dbId && SB){
        await SB.from('comments').insert({post_id:p.dbId, user_name:profile.username, avatar:profile.avatar, content:txt, device_id:DEVICE_ID});
      } else {
        store.set('posts', seed);
      }
      renderFeed();
    };
    box.querySelector('.comment-send').addEventListener('click', send);
    input.addEventListener('keydown', (e)=>{ if(e.key==='Enter') send(); });

    list.appendChild(el);
  });
}

function escapeHtml(s){ return s.replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

function renderTop(){
  const top = store.get('topList', []);
  const profile = getProfile();
  const record = store.get('record', 0);
  const combined = [...top, {name:profile.username+' '+t('youSuffix'), avatar:profile.avatar, alt:record, me:true}].sort((a,b)=>b.alt-a.alt);
  const list = document.getElementById('topList');
  const locale = LANG==='en'?'en-US':LANG==='tr'?'tr-TR':'az-AZ';
  list.innerHTML = '';
  combined.forEach((p, i)=>{
    const row = document.createElement('div');
    row.className = 'top-row rank-'+(i+1);
    row.innerHTML = `<span class="top-rank">${i+1}</span>
      <img class="top-avatar" src="${p.avatar}" alt="">
      <span class="top-name">${p.name}</span>
      <span class="top-alt">${p.alt.toLocaleString(locale)} m</span>`;
    list.appendChild(row);
  });
}

