/* ============================================================
   PROFİL
   ============================================================ */
function getProfile(){
  return store.get('profile', {username:t('defaultUser'), bio:'', avatar:avatarFor(t('defaultUser'))});
}

function initProfil(){
  const profile = getProfile();
  document.getElementById('usernameInput').value = profile.username;
  document.getElementById('bioInput').value = profile.bio;
  document.getElementById('avatarImg').src = profile.avatar;

  document.getElementById('usernameInput').addEventListener('input', (e)=>{ profile.username = e.target.value || t('defaultUser'); store.set('profile', profile); });
  document.getElementById('bioInput').addEventListener('input', (e)=>{ profile.bio = e.target.value; store.set('profile', profile); });
  document.getElementById('avatarInput').addEventListener('change', (e)=>{
    const file = e.target.files[0]; if(!file) return;
    const reader = new FileReader();
    reader.onload = ()=>{ profile.avatar = reader.result; store.set('profile', profile); document.getElementById('avatarImg').src = profile.avatar; toast(t('toast.avatar')); };
    reader.readAsDataURL(file);
  });
  renderProfileScreen();
}

function renderProfileScreen(){
  const record = store.get('record', 0);
  const posts = store.get('posts', []).filter(p => p.user === getProfile().username);
  const cards = store.get('myCards', []);
  const locale = LANG==='en'?'en-US':LANG==='tr'?'tr-TR':'az-AZ';

  document.getElementById('recordAlt').textContent = record.toLocaleString(locale);
  document.getElementById('postCount').textContent = posts.length;

  const top = store.get('topList', []);
  const all = [...top.map(x=>x.alt), record].sort((a,b)=>b-a);
  const rank = all.indexOf(record) + 1;
  document.getElementById('rankValue').textContent = record > 0 ? '#'+rank : '—';

  const grid = document.getElementById('myCardsGrid');
  if(cards.length === 0){ grid.innerHTML = `<div class="empty-hint">${t('app.noCards')}</div>`; return; }
  grid.innerHTML = '';
  cards.forEach(c=>{
    const img = document.createElement('img');
    img.className = 'my-card-thumb'; img.src = c.img; img.alt = c.alt+' m';
    grid.appendChild(img);
  });
}

/* ============================================================
   EFFECT 1 — SPOTLIGHT (pointer-follow glow on cards)
   Sets viewport pointer coords as CSS vars; CSS does the glow.
   ============================================================ */
function initSpotlight(){
  const root = document.documentElement;
  let raf = 0, px = -999, py = -999;
  window.addEventListener('pointermove', (e)=>{
    px = e.clientX; py = e.clientY;
    if(!raf) raf = requestAnimationFrame(()=>{
      root.style.setProperty('--mx', px);
      root.style.setProperty('--my', py);
      raf = 0;
    });
  }, {passive:true});
}

/* ============================================================
   EFFECT 2 — KINETIC GRID (interactive warping canvas bg)
   Vanilla port of the KineticGrid React component (zirve theme).
   ============================================================ */
function mountKineticGrid(canvas){
  const ctx = canvas.getContext('2d');
  const CELL=55, INFLUENCE=220, MAXWARP=20, DOT=28, LERP=0.09;
  const LINE_BASE={r:255,g:255,b:255,a:0.10};
  const theme={bg:null, line:{r:127,g:221,b:235}, node:{r:255,g:61,b:46}, glow:'255,61,46', ripple:'127,221,235'};
  let W=0,H=0, mx=-9999,my=-9999, tx=-9999,ty=-9999, ripples=[], raf=0, running=false;

  function size(){
    const r=canvas.getBoundingClientRect();
    W=canvas.width=Math.max(1,Math.round(r.width));
    H=canvas.height=Math.max(1,Math.round(r.height));
  }
  const lerp=(a,b,t)=>a+(b-a)*t;
  function lc(base,act,t){
    return `rgba(${Math.round(lerp(base.r,act.r,t))},${Math.round(lerp(base.g,act.g,t))},${Math.round(lerp(base.b,act.b,t))},${lerp(base.a,act.a??1,t).toFixed(3)})`;
  }
  function warp(gx,gy,col,row,cols,rows){
    const em=1.5;
    const cp=Math.min(col/em,(cols-1-col)/em,1), rp=Math.min(row/em,(rows-1-row)/em,1);
    const pin=cp*cp*rp*rp;
    const dx=gx-mx, dy=gy-my, dist=Math.hypot(dx,dy);
    const prox=Math.max(0,1-dist/INFLUENCE)*pin;
    let rx=0,ry=0;
    for(const r of ripples){
      const diff=Math.hypot(gx-r.x,gy-r.y)-r.radius, ww=55;
      if(Math.abs(diff)<ww){
        const s=(1-Math.abs(diff)/ww)*r.opacity*16*pin, ang=Math.atan2(gy-r.y,gx-r.x), sg=diff<0?-1:1;
        rx+=Math.cos(ang)*s*sg*-1; ry+=Math.sin(ang)*s*sg*-1;
      }
    }
    if(dist<INFLUENCE&&dist>0&&pin>0){
      const tt=dist/INFLUENCE, e=tt<0.01?0:(1-tt)*(1-tt)*Math.min(1,dist/60), wa=e*MAXWARP*pin, ang=Math.atan2(dy,dx);
      return {x:gx-Math.cos(ang)*wa+rx, y:gy-Math.sin(ang)*wa+ry, p:prox};
    }
    return {x:gx+rx, y:gy+ry, p:prox};
  }
  function draw(now){
    mx=lerp(mx,tx,LERP); my=lerp(my,ty,LERP);
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle='rgba(255,255,255,0.04)';
    for(let x=DOT/2;x<W;x+=DOT) for(let y=DOT/2;y<H;y+=DOT){ ctx.beginPath(); ctx.arc(x,y,0.7,0,6.283); ctx.fill(); }
    for(let i=ripples.length-1;i>=0;i--){ const r=ripples[i], age=(now-r.born)/1000; r.radius=Math.max(0,age*380); r.opacity=Math.max(0,1-age*1.2); if(r.opacity<=0) ripples.splice(i,1); }
    const cols=Math.max(2,Math.ceil(W/CELL))+1, rows=Math.max(2,Math.ceil(H/CELL))+1;
    const cw=W/(cols-1), ch=H/(rows-1);
    const pts=[], pr=[];
    for(let row=0;row<rows;row++){ pts[row]=[]; pr[row]=[]; for(let col=0;col<cols;col++){ const w=warp(col*cw,row*ch,col,row,cols,rows); pts[row][col]={x:w.x,y:w.y}; pr[row][col]=w.p; } }
    const seg=(p1,p2,a,b)=>{ const avg=(a+b)/2, t=avg*avg*(3-2*avg); ctx.beginPath(); ctx.moveTo(p1.x,p1.y); ctx.lineTo(p2.x,p2.y); ctx.strokeStyle=lc(LINE_BASE,{...theme.line,a:0.9},t); ctx.lineWidth=lerp(0.7,1.4,t); ctx.stroke(); };
    for(let row=0;row<rows;row++) for(let col=0;col<cols-1;col++) seg(pts[row][col],pts[row][col+1],pr[row][col],pr[row][col+1]);
    for(let col=0;col<cols;col++) for(let row=0;row<rows-1;row++) seg(pts[row][col],pts[row+1][col],pr[row][col],pr[row+1][col]);
    for(let row=0;row<rows;row++) for(let col=0;col<cols;col++){
      const p=pts[row][col], t=pr[row][col]*pr[row][col]*(3-2*pr[row][col]), rad=lerp(1.6,3,t);
      if(t>0.3){ const gr=rad+lerp(0,6,(t-0.3)/0.7), g=ctx.createRadialGradient(p.x,p.y,rad*0.5,p.x,p.y,gr); g.addColorStop(0,`rgba(${theme.glow},${(t*0.3).toFixed(3)})`); g.addColorStop(1,`rgba(${theme.glow},0)`); ctx.beginPath(); ctx.arc(p.x,p.y,gr,0,6.283); ctx.fillStyle=g; ctx.fill(); }
      ctx.beginPath(); ctx.arc(p.x,p.y,rad,0,6.283); ctx.fillStyle=lc({r:255,g:255,b:255,a:0.18},{...theme.node,a:1},t); ctx.fill();
    }
    for(const r of ripples){ ctx.beginPath(); ctx.arc(r.x,r.y,Math.max(0,r.radius),0,6.283); ctx.strokeStyle=`rgba(${theme.ripple},${(r.opacity*0.28).toFixed(3)})`; ctx.lineWidth=1.5; ctx.stroke(); }
    raf=requestAnimationFrame(draw);
  }
  function toLocal(e){ const r=canvas.getBoundingClientRect(); return {x:e.clientX-r.left, y:e.clientY-r.top}; }
  const host = canvas.parentElement;
  host.addEventListener('pointermove', (e)=>{ const l=toLocal(e); tx=l.x; ty=l.y; });
  host.addEventListener('pointerleave', ()=>{ tx=-9999; ty=-9999; });
  host.addEventListener('click', (e)=>{ const l=toLocal(e); ripples.push({x:l.x,y:l.y,radius:0,opacity:1,born:performance.now()}); });
  window.addEventListener('resize', size);
  size();
  // Only animate while the section is on-screen (perf)
  const io=new IntersectionObserver((es)=>{ es.forEach(en=>{
    if(en.isIntersecting && !running){ running=true; raf=requestAnimationFrame(draw); }
    else if(!en.isIntersecting && running){ running=false; cancelAnimationFrame(raf); }
  }); }, {threshold:0.01});
  io.observe(canvas);
}
function initKinetic(){
  if(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const c=document.getElementById('kineticCanvas');
  if(c) mountKineticGrid(c);
}

/* ============================================================
   EFFECT 3 — SCROLL-EXPAND MEDIA
   Media scales small→full as the section scrolls through view.
   ============================================================ */
function initScrollExpand(){
  const sec=document.getElementById('expandSection');
  if(!sec) return;
  const media=sec.querySelector('.expand-media');
  const content=sec.querySelector('.expand-content');
  const onScroll=()=>{
    const r=sec.getBoundingClientRect();
    const vh=window.innerHeight;
    // How far we've scrolled into the tall section (sticky travel range)
    const scrolledInto=-r.top;
    const range=Math.max(1, sec.offsetHeight - vh);
    // Expand over the first 65% of the travel, then hold
    const p=Math.min(1, Math.max(0, scrolledInto / (range*0.65)));
    const eased=1-Math.pow(1-p,3);
    media.style.setProperty('--exp', eased.toFixed(3));
    content.style.opacity = p>0.7 ? ((p-0.7)/0.3).toFixed(2) : '0';
  };
  window.addEventListener('scroll', onScroll, {passive:true});
  window.addEventListener('resize', onScroll);
  onScroll();
}

/* ============================================================
   BRANDED GENERATIVE SCENES (replace stock photos)
   Deterministic layered alpine SVG in the Zirvə palette.
   ============================================================ */
function mulberry32(a){ return function(){ a|=0; a=a+0x6D2B79F5|0; let t=Math.imul(a^a>>>15,1|a); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }

const SCENE_VARIANTS = {
  dusk:  {sky:['#26384d','#182437','#0B1220'], sunCore:'#F2A987', sunGlow:'rgba(232,138,94,0.55)', sunY:0.34, ridges:['#2c3e57','#22344e','#182740','#101d31'], snow:'rgba(245,245,240,0.18)', stars:false},
  night: {sky:['#14243a','#0e1626','#070b14'], sunCore:'#FF6B3D', sunGlow:'rgba(255,61,46,0.45)', sunY:0.60, ridges:['#1b2a44','#152039','#101833','#0a1121'], snow:'rgba(245,245,240,0.14)', stars:true},
  ice:   {sky:['#1d3340','#132630','#0b141d'], sunCore:'#A8ECF5', sunGlow:'rgba(127,221,235,0.42)', sunY:0.32, ridges:['#234550','#1a343c','#12262d','#0c1a20'], snow:'rgba(245,245,240,0.22)', stars:false},
  ember: {sky:['#2c1c13','#1a0f0a','#0B1220'], sunCore:'#FF9E6B', sunGlow:'rgba(255,109,61,0.5)', sunY:0.38, ridges:['#3d2519','#2c1a11','#1b0f0a','#0f0a09'], snow:'rgba(245,245,240,0.12)', stars:false},
};

function ridgePath(rnd, W, H, baseY, amp, sharp){
  const n = 9 + Math.floor(rnd()*4);
  let d = `M0,${H} L0,${(baseY+amp*0.4).toFixed(0)}`;
  for(let i=0;i<=n;i++){
    const x = (W*i/n).toFixed(0);
    const jag = Math.pow(rnd(), sharp);
    const y = (baseY - jag*amp).toFixed(0);
    d += ` L${x},${y}`;
  }
  d += ` L${W},${H} Z`;
  return d;
}

function makeScene(seed=1, variant='dusk'){
  const rnd = mulberry32(seed*2654435761 >>> 0);
  const V = SCENE_VARIANTS[variant] || SCENE_VARIANTS.dusk;
  const W=1600, H=1200;
  const sunX = (0.2 + rnd()*0.6)*W, sunY = V.sunY*H;

  let stars='';
  if(V.stars){
    for(let i=0;i<60;i++){
      const x=(rnd()*W).toFixed(0), y=(rnd()*H*0.55).toFixed(0), r=(rnd()*1.6+0.3).toFixed(1), o=(rnd()*0.5+0.2).toFixed(2);
      stars += `<circle cx="${x}" cy="${y}" r="${r}" fill="rgba(245,245,240,${o})"/>`;
    }
  }

  let ridges='';
  const layers=4;
  for(let i=0;i<layers;i++){
    const baseY = H*(0.5 + i*0.12);
    const amp = H*(0.14 + i*0.05);
    const sharp = 1.4 + i*0.5;
    ridges += `<path d="${ridgePath(rnd, W, H, baseY, amp, sharp)}" fill="${V.ridges[i]}"/>`;
    // subtle crest highlight on the two front ridges
    if(i>=2){
      const hy = baseY - amp*0.02;
      ridges += `<path d="${ridgePath(rnd, W, H, hy, amp, sharp)}" fill="none" stroke="${V.snow}" stroke-width="3"/>`;
    }
  }

  const svg =
`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 ${W} ${H}' preserveAspectRatio='xMidYMid slice'>
<defs>
<linearGradient id='sky' x1='0' y1='0' x2='0' y2='1'>
<stop offset='0' stop-color='${V.sky[0]}'/><stop offset='0.55' stop-color='${V.sky[1]}'/><stop offset='1' stop-color='${V.sky[2]}'/>
</linearGradient>
<radialGradient id='sun' cx='${(sunX/W).toFixed(3)}' cy='${(sunY/H).toFixed(3)}' r='0.5'>
<stop offset='0' stop-color='${V.sunGlow}'/><stop offset='1' stop-color='rgba(0,0,0,0)'/>
</radialGradient>
<filter id='grain'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter>
</defs>
<rect width='${W}' height='${H}' fill='url(#sky)'/>
${stars}
<rect width='${W}' height='${H}' fill='url(#sun)'/>
<circle cx='${sunX.toFixed(0)}' cy='${sunY.toFixed(0)}' r='${(W*0.05).toFixed(0)}' fill='${V.sunCore}' opacity='0.9'/>
${ridges}
<rect width='${W}' height='${H}' filter='url(#grain)' opacity='0.05'/>
</svg>`;

  return 'data:image/svg+xml,' + encodeURIComponent(svg);
}

/* Drop real photos in zirve-pro/assets/ and map them here.
   Any slot left null falls back to a generative branded scene.
   e.g.  hero: 'assets/hero.jpg'                                */
const USER_IMAGES = {
  hero:    null,
  hero2:   null,
  feature1:null,
  feature2:null,
  featureFull:null,
  expand:  null,
  post1:   null,
  post2:   null,
  post3:   null,
};

function sceneOrPhoto(key, seed, variant){
  return USER_IMAGES[key] || makeScene(seed, variant);
}

function initScenes(){
  const bg = (sel, uri)=>{ const el=document.querySelector(sel); if(el) el.style.backgroundImage = `url("${uri}")`; };
  bg('.hero-photo',   sceneOrPhoto('hero', 11,'night'));
  bg('.hero-photo-2', sceneOrPhoto('hero2', 23,'dusk'));
  const medias = document.querySelectorAll('.feature-media');
  if(medias[0]) medias[0].style.backgroundImage = `url("${sceneOrPhoto('feature1', 7,'ice')}")`;
  if(medias[1]) medias[1].style.backgroundImage = `url("${sceneOrPhoto('feature2', 31,'ember')}")`;
  bg('.feature-full-bg', sceneOrPhoto('featureFull', 19,'dusk'));
  const exp = document.querySelector('.expand-media img'); if(exp) exp.src = sceneOrPhoto('expand', 42,'night');

  preloadSceneImg(77, 'dusk').then(()=>{ drawCard(); buildLayoutThumbs(); });
}

/* ============================================================
   CRAFTED MICRO-INTERACTIONS
   ============================================================ */
const finePointer = window.matchMedia && window.matchMedia('(pointer:fine)').matches;
const reducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

/* Sliding segmented indicator for a group of buttons */
function initSegmented(container, btnSelector){
  if(!container) return;
  const btns = [...container.querySelectorAll(btnSelector)];
  if(!btns.length) return;
  const thumb = document.createElement('span');
  thumb.className = 'seg-thumb';
  container.appendChild(thumb);
  container.classList.add('has-thumb');

  const move = (btn)=>{
    if(!btn) return;
    thumb.style.width = btn.offsetWidth + 'px';
    thumb.style.height = btn.offsetHeight + 'px';
    thumb.style.transform = `translate(${btn.offsetLeft}px, ${btn.offsetTop}px)`;
    thumb.style.opacity = '1';
  };
  const active = ()=> container.querySelector(btnSelector + '.active') || btns[0];
  requestAnimationFrame(()=> move(active()));
  // move synchronously on click so it responds even when rAF is throttled
  btns.forEach(b=> b.addEventListener('click', ()=> move(b)));
  window.addEventListener('resize', ()=> move(active()));
  // expose for external re-sync (e.g. after language switch relayout)
  container._segMove = ()=> move(active());
}

/* Magnetic pull toward cursor (desktop only) */
function initMagnetic(){
  if(!finePointer || reducedMotion) return;
  const els = document.querySelectorAll('.alt-cta, .nav-cta, .btn-primary');
  els.forEach(el=>{
    const strength = 0.28;
    el.addEventListener('pointermove', (e)=>{
      const r = el.getBoundingClientRect();
      const mx = e.clientX - (r.left + r.width/2);
      const my = e.clientY - (r.top + r.height/2);
      el.style.transform = `translate(${(mx*strength).toFixed(1)}px, ${(my*strength - 2).toFixed(1)}px)`;
    });
    el.addEventListener('pointerleave', ()=>{ el.style.transform = ''; });
  });
}

/* Subtle pointer tilt on small cards */
function initTilt(){
  if(!finePointer || reducedMotion) return;
  const cards = document.querySelectorAll('.wx-card, .info-card, .fc, .top-row');
  cards.forEach(card=>{
    card.addEventListener('pointermove', (e)=>{
      const r = card.getBoundingClientRect();
      const px = (e.clientX - r.left)/r.width - 0.5;
      const py = (e.clientY - r.top)/r.height - 0.5;
      const max = 4;
      card.style.transform =
        `perspective(600px) rotateY(${(px*max).toFixed(2)}deg) rotateX(${(-py*max).toFixed(2)}deg) translateY(-3px)`;
    });
    card.addEventListener('pointerleave', ()=>{ card.style.transform = ''; });
  });
}

function initCraftedInteractions(){
  initSegmented(document.getElementById('langSwitch'), 'button');
  initSegmented(document.querySelector('.social-nav'), '.snav-btn');
  initMagnetic();
  initTilt();
}

